CREATE TYPE "WhatsAppCampaignAudience" AS ENUM ('CONFIRMED_REGISTRATIONS', 'TICKET_HOLDERS');
CREATE TYPE "WhatsAppCampaignStatus" AS ENUM ('DRAFT', 'SCHEDULED', 'SENDING', 'COMPLETED', 'CANCELLED');
CREATE TABLE "whatsapp_campaigns" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "organizer_id" UUID NOT NULL, "event_id" UUID NOT NULL, "name" VARCHAR(120) NOT NULL, "message" VARCHAR(2000) NOT NULL, "audience" "WhatsAppCampaignAudience" NOT NULL, "status" "WhatsAppCampaignStatus" NOT NULL DEFAULT 'DRAFT', "scheduled_at" TIMESTAMPTZ, "created_by" UUID NOT NULL, "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(), "updated_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(), "cancelled_at" TIMESTAMPTZ, CONSTRAINT "whatsapp_campaigns_pkey" PRIMARY KEY ("id"), CONSTRAINT "whatsapp_campaigns_organizer_fk" FOREIGN KEY ("organizer_id") REFERENCES "organizers"("id") ON DELETE CASCADE, CONSTRAINT "whatsapp_campaigns_event_fk" FOREIGN KEY ("event_id") REFERENCES "events"("id") ON DELETE CASCADE, CONSTRAINT "whatsapp_campaigns_created_by_fk" FOREIGN KEY ("created_by") REFERENCES "users"("id") ON DELETE RESTRICT);
CREATE TABLE "whatsapp_campaign_recipients" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "campaign_id" UUID NOT NULL, "user_id" UUID NOT NULL, "phone_e164" VARCHAR(16) NOT NULL, "intent_id" UUID, "status" VARCHAR(32) NOT NULL DEFAULT 'PENDING', "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(), "updated_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT "whatsapp_campaign_recipients_pkey" PRIMARY KEY ("id"), CONSTRAINT "whatsapp_campaign_recipients_campaign_fk" FOREIGN KEY ("campaign_id") REFERENCES "whatsapp_campaigns"("id") ON DELETE CASCADE, CONSTRAINT "whatsapp_campaign_recipients_user_fk" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT, CONSTRAINT "whatsapp_campaign_recipients_intent_fk" FOREIGN KEY ("intent_id") REFERENCES "notification_intents"("id") ON DELETE SET NULL, CONSTRAINT "whatsapp_campaign_recipients_unique" UNIQUE ("campaign_id", "user_id"));
CREATE INDEX "whatsapp_campaigns_organizer_status_idx" ON "whatsapp_campaigns"("organizer_id", "status", "created_at");
CREATE INDEX "whatsapp_campaigns_event_idx" ON "whatsapp_campaigns"("event_id", "status");
CREATE INDEX "whatsapp_campaign_recipients_campaign_status_idx" ON "whatsapp_campaign_recipients"("campaign_id", "status");
CREATE INDEX "whatsapp_campaign_recipients_user_idx" ON "whatsapp_campaign_recipients"("user_id");